import React, { useState, useEffect } from "react";
import { useSelector } from "react-redux";
import Modal from "../../../components/ui/Modal";
import Button from "../../../components/ui/Button";
import Icon from "../../../components/AppIcon";
import { cn } from "../../../utils/cn";
import { supabaseService } from "../../../services/supabaseService";
import { useToast } from "../../../contexts/ToastContext";
import {
  formatLuc,
  formatNaira,
  nairaToLuc,
} from "../../../utils/currencyUtils";
import { getStoredReferralCode, getStoredPromoCode, clearStoredDiscountParams } from "../../../utils/discountParams";
import IntegrityAgreementModal from "./IntegrityAgreementModal";
import CampIntakeModal from "./CampIntakeModal";

const PaymentModal = ({ isOpen, onClose, course, onPaymentSuccess, campSettings, preFilledIntakeData }) => {
  const { user } = useSelector((state) => state.auth);
  const { addToast } = useToast();
  const [step, setStep] = useState("checkout"); // checkout -> processing -> success
  const [isLoading, setIsLoading] = useState(false);
  const [wallet, setWallet] = useState({ balance: 0 });
  const [isFetchingWallet, setIsFetchingWallet] = useState(false);
  const [showIntegrityModal, setShowIntegrityModal] = useState(false);
  const [promoInput, setPromoInput] = useState("");
  const [appliedPromo, setAppliedPromo] = useState(null);
  const [showIntakeModal, setShowIntakeModal] = useState(false);
  const [intakeData, setIntakeData] = useState(null);
  const [packageType, setPackageType] = useState('standard');
  const [numChildren, setNumChildren] = useState(2);
  const [referralCode, setReferralCode] = useState('');
  const [referralValid, setReferralValid] = useState(false);
  const [verifyingReferral, setVerifyingReferral] = useState(false);
  const [instructorPromoCode, setInstructorPromoCode] = useState('');
  const [instructorPromoValid, setInstructorPromoValid] = useState(false);
  const [instructorPromoData, setInstructorPromoData] = useState(null);
  const [verifyingInstructorPromo, setVerifyingInstructorPromo] = useState(false);
  const [autoAppliedReferral, setAutoAppliedReferral] = useState(false);
  const [autoAppliedPromo, setAutoAppliedPromo] = useState(false);
  const [platformPromoData, setPlatformPromoData] = useState(null);
  const [verifyingPlatformPromo, setVerifyingPlatformPromo] = useState(false);
  const [autoAppliedPlatformPromo, setAutoAppliedPlatformPromo] = useState(false);
  const [showBankTransfer, setShowBankTransfer] = useState(null); // null | 'opay' | 'kuda'
  const [paymentConfirmed, setPaymentConfirmed] = useState(false);

  const bankDetails = {
      opay: { bank: 'Opay', accountNumber: '9132438685', accountName: 'Promise Ingnatius Chikwendu' },
      kuda: { bank: 'Kuda', accountNumber: '3004074352', accountName: 'Promise Ingnatius' },
  };

  const needsIntake = course?.requiresIntakeForm && !intakeData;

  // Determine current window state from campSettings prop
  const getWindowState = () => {
    if (!campSettings?.early_registration_end) return 'standard';
    const now = new Date();
    const earlyEnd = new Date(campSettings.early_registration_end);
    const campStart = campSettings.camp_start_date ? new Date(campSettings.camp_start_date) : null;
    const campEnd = campSettings.camp_end_date ? new Date(campSettings.camp_end_date) : null;

    if (now < earlyEnd) return 'early';
    if (campStart && campEnd && now >= campStart && now < campEnd) return 'live';
    if (campEnd && now >= campEnd) return 'ended';
    return 'standard';
  };

  const windowState = getWindowState();
  const isEarlyWindow = windowState === 'early';

  // ── Pricing logic ──
  let basePrice = course?.price || 0;
  let discountLabel = '';

  if (isEarlyWindow) {
    // WITHIN 72-HOUR EARLY REGISTRATION WINDOW
    if (packageType === 'sibling' && numChildren > 1) {
      // Parent registering 2+ children: 15% off
      basePrice = (course?.price || 0) * numChildren * 0.85;
      discountLabel = `15% off for ${numChildren} children (Early Bird)`;
    } else if (packageType === 'referral' && referralValid) {
      // Referral code: 10% off
      basePrice = (course?.price || 0) * 0.9;
      discountLabel = '10% referral discount (Early Bird)';
    } else if (packageType === 'early_bird') {
      // Student self-registering with early bird selected: 10% off
      basePrice = (course?.price || 0) * 0.9;
      discountLabel = '10% Early Bird discount';
    } else {
      // Standard (no discount applied yet)
      basePrice = course?.price || 0;
    }
  } else {
    // AFTER EARLY REGISTRATION WINDOW
    if (packageType === 'sibling' && numChildren > 1) {
      // Parent registering 2+ children: 10% off (reduced from 15%)
      basePrice = (course?.price || 0) * numChildren * 0.9;
      discountLabel = `10% off for ${numChildren} children`;
    } else if (packageType === 'referral' && referralValid) {
      // Referral code: 10% off (only way to get discount for self-reg after window)
      basePrice = (course?.price || 0) * 0.9;
      discountLabel = '10% referral discount';
    } else {
      // Student self-registering: NO discount (full price)
      basePrice = course?.price || 0;
      if (packageType === 'early_bird') {
        discountLabel = 'Early Bird expired — full price';
      }
    }
  }

  // Apply promo code on top of everything
  const calculatedPrice = basePrice;
  const hasInstructorDiscount = instructorPromoValid && instructorPromoData;
  const priceAfterInstructorPromo = hasInstructorDiscount
    ? Math.max(0, calculatedPrice - (calculatedPrice * (instructorPromoData.discount_percent / 100)))
    : calculatedPrice;
  const hasPlatformDiscount = course?.isTrack && platformPromoData && platformPromoData.discount_percent > 0;
  const priceAfterPlatformPromo = hasPlatformDiscount
    ? Math.max(0, priceAfterInstructorPromo - (priceAfterInstructorPromo * (platformPromoData.discount_percent / 100)))
    : priceAfterInstructorPromo;
  const finalPrice = appliedPromo
    ? Math.max(0, priceAfterPlatformPromo - (priceAfterPlatformPromo * (appliedPromo.discountPercent / 100)))
    : priceAfterPlatformPromo;

  const finalizePayment = async (course, reference) => {
      if (packageType === 'referral' && referralValid && referralCode) {
          try {
              const { data } = await supabaseService.client
                  .from('profiles')
                  .select('id')
                  .eq('referral_code', referralCode.trim())
                  .single();
              if (data?.id) {
                  const bonusAmount = (course?.price || 0) * 0.10;
                  await supabaseService.processWalletTransaction(
                      data.id,
                      nairaToLuc(bonusAmount),
                      'referral_bonus',
                      `Referral bonus for ${course.title}`,
                      `ref_bonus_${reference}`
                  );
              }
          } catch (err) {
              console.error("Failed to process referral bonus", err);
          }
      }

      if (instructorPromoValid && instructorPromoData) {
          try {
              const trackPrice = course?.isTrack ? (course?.price || 0) : (course?.price || 0);
              const discountAmount = trackPrice * (instructorPromoData.discount_percent / 100);
              const lucCredit = nairaToLuc(discountAmount);
              await supabaseService.processWalletTransaction(
                  instructorPromoData.instructor_id,
                  lucCredit,
                  'instructor_promo_bonus',
                  `Promo code bonus for ${course.title}`,
                  `promo_bonus_${reference}`
              );
              await supabaseService.recordInstructorPromoUsage(
                  instructorPromoData.id,
                  instructorPromoData.instructor_id,
                  user?.id,
                  course.id,
                  discountAmount,
                  lucCredit
              );
          } catch (err) {
              console.error("Failed to process instructor promo bonus", err);
          }
      }

      // Track platform promo usage and credit the holder (track enrollments only)
      if (course?.isTrack && platformPromoData) {
          try {
              const originalPrice = course?.price || 0;
              const discountAmt = originalPrice * (platformPromoData.discount_percent / 100);
              const rewardLuc = platformPromoData.reward_per_enrollment_luc || 0;

              await supabaseService.recordPlatformPromoUsage({
                  promoCodeId: platformPromoData.id,
                  userId: user?.id,
                  courseId: course.id,
                  courseTitle: course.title,
                  originalPrice: originalPrice,
                  discountAmount: discountAmt,
                  finalPrice: finalPrice,
                  rewardLucCredited: rewardLuc,
                  paymentReference: reference
              });

              // Credit the promo code holder if reward is set
              if (rewardLuc > 0) {
                  await supabaseService.processWalletTransaction(
                      platformPromoData.created_by,
                      rewardLuc,
                      'platform_promo_reward',
                      `Promo code reward: ${platformPromoData.code} used for ${course.title}`,
                      `promo_reward_${reference}`
                  );
              }
          } catch (err) {
              console.error("Failed to record platform promo usage", err);
          }
      }

      onPaymentSuccess(course, reference);
  };

  const handleVerifyReferral = async () => {
      if (!referralCode.trim()) return;
      setVerifyingReferral(true);
      try {
          const { data } = await supabaseService.client
              .from('profiles')
              .select('id')
              .eq('referral_code', referralCode.trim())
              .single();
              
          if (data && data.id !== user?.id) {
              setReferralValid(true);
              setInstructorPromoCode('');
              setInstructorPromoValid(false);
              setInstructorPromoData(null);
              addToast("Referral code verified! 10% discount applied.", "success");
          } else {
              setReferralValid(false);
              addToast(data?.id === user?.id ? "You cannot refer yourself." : "Invalid referral code.", "error");
          }
      } catch (err) {
          setReferralValid(false);
          addToast("Invalid referral code.", "error");
      } finally {
          setVerifyingReferral(false);
      }
  };

  const handleVerifyInstructorPromo = async () => {
      if (!instructorPromoCode.trim() || !course?.id) return;
      setVerifyingInstructorPromo(true);
      try {
          const trackCourseIds = course.isTrack ? (course.courses || []).map(String) : null;
          const promo = await supabaseService.validateInstructorPromoCode(
              instructorPromoCode.trim(),
              course.isTrack ? null : course.id,
              trackCourseIds
          );
          if (promo) {
              setInstructorPromoValid(true);
              setInstructorPromoData(promo);
              setReferralCode('');
              setReferralValid(false);
              addToast(`Instructor code verified! ${promo.discount_percent}% discount applied.`, "success");
          } else {
              setInstructorPromoValid(false);
              setInstructorPromoData(null);
              addToast("Invalid instructor code or not applicable to this track's courses.", "error");
          }
      } catch (err) {
          setInstructorPromoValid(false);
          setInstructorPromoData(null);
          addToast("Invalid instructor code.", "error");
      } finally {
          setVerifyingInstructorPromo(false);
      }
  };

  useEffect(() => {
    if (isOpen && user?.id) {
      fetchUserWallet();
      setPromoInput("");
      setAppliedPromo(null);
      setAutoAppliedReferral(false);
      setAutoAppliedPromo(false);
      setAutoAppliedPlatformPromo(false);
      setPlatformPromoData(null);

      // If we already have intake data from the guest flow, use it directly
      if (preFilledIntakeData) {
        const intake = preFilledIntakeData.studentsData ? preFilledIntakeData : preFilledIntakeData;
        setIntakeData(intake);
        setShowIntakeModal(false);

        // Auto-save the camp registration and apply sibling discount
        (async () => {
          try {
            const studentsToSave = intake.studentsData ? intake.studentsData : [intake];
            const record = {
                studentFullName: studentsToSave[0]?.studentFullName,
                studentAge: studentsToSave[0]?.studentAge,
                attendanceFormat: studentsToSave[0]?.attendanceFormat,
                track: studentsToSave[0]?.track,
                goal: studentsToSave[0]?.goal,
                user_id: user?.id,
                course_id: course?.id,
                course_title: course?.title,
                registration_type: intake.registrationRole || 'student',
                parent_whatsapp: intake.parentWhatsapp || null,
                parent_name: intake.parentName || null,
                studentsData: studentsToSave
            };
            await supabaseService.client
                .from('camp_registrations')
                .insert([record]);

            if (studentsToSave.length > 1) {
                setPackageType('sibling');
                setNumChildren(studentsToSave.length);
            }
          } catch (err) {
            console.warn("Pre-filled intake save failed (non-blocking):", err.message);
          }
        })();
      } else if (course?.requiresIntakeForm) {
        // No pre-filled data — show intake form as usual
        setIntakeData(null);
        setShowIntakeModal(true);
      } else {
        setIntakeData(null);
        setShowIntakeModal(false);
      }

      // Auto-apply codes from URL params (stored in localStorage)
      const storedRef = getStoredReferralCode();
      const storedPromo = getStoredPromoCode();

      if (storedRef) {
        setReferralCode(storedRef);
        setPackageType('referral');
        // Auto-verify referral code
        (async () => {
          try {
            const { data } = await supabaseService.client
              .from('profiles')
              .select('id')
              .eq('referral_code', storedRef)
              .single();
            if (data && data.id !== user?.id) {
              setReferralValid(true);
              setAutoAppliedReferral(true);
              setInstructorPromoCode('');
              setInstructorPromoValid(false);
              setInstructorPromoData(null);
            }
          } catch (err) {
            console.error('Auto-apply referral failed:', err);
          }
        })();
      }

      if (storedPromo && course?.isTrack) {
        (async () => {
          // Try platform promo codes first (track enrollments only)
          let platformApplied = false;
          try {
            const platformPromo = await supabaseService.validatePlatformPromoCode(storedPromo);
            if (platformPromo) {
              setPlatformPromoData(platformPromo);
              setAutoAppliedPlatformPromo(true);
              setAppliedPromo(null);
              platformApplied = true;
            }
          } catch (err) {
            // Silent — not a platform promo code
          }

          // If platform promo didn't match, try instructor promo codes
          if (!platformApplied) {
            try {
              const trackCourseIds = (course.courses || []).map(String);
              const instructorPromo = await supabaseService.validateInstructorPromoCode(
                  storedPromo,
                  null,
                  trackCourseIds
                );
                if (instructorPromo) {
                  setInstructorPromoCode(storedPromo);
                  setInstructorPromoValid(true);
                  setInstructorPromoData(instructorPromo);
                  setAutoAppliedPromo(true);
                  setReferralCode('');
                  setReferralValid(false);
                }
              } catch (err) {
                // Silent — not an instructor promo code or not applicable
              }
            }
        })();
      }

      // Clear stored params after reading (one-time use)
      if (storedRef || storedPromo) {
        clearStoredDiscountParams();
      }
    }
  }, [isOpen, user?.id, course?.id]);

  const fetchUserWallet = async () => {
    setIsFetchingWallet(true);
    try {
      const data = await supabaseService.getUserWallet(user.id);
      setWallet(data);
    } catch (error) {
      console.error("Failed to fetch wallet:", error);
    } finally {
      setIsFetchingWallet(false);
    }
  };

  const handleBankTransfer = (bank) => {
    if (!user || !user.email) {
      alert("Please log in to complete payment");
      return;
    }
    setShowBankTransfer(bank);
  };

  const handleConfirmPayment = async () => {
    setIsLoading(true);
    setPaymentConfirmed(true);
    setStep("processing");
    try {
      await supabaseService.createPaymentRequest({
        userId: user.id,
        courseId: String(course.id),
        courseTitle: course.title,
        isTrack: !!course.isTrack,
        trackId: course.isTrack ? String(course.id) : null,
        trackTitle: course.isTrack ? course.title : null,
        amount: finalPrice,
        bank: showBankTransfer,
        promoCodeId: platformPromoData?.id || null,
        promoType: platformPromoData ? 'platform' : (instructorPromoValid && instructorPromoData ? 'instructor' : null),
        promoDiscountPercent: platformPromoData?.discount_percent || instructorPromoData?.discount_percent || 0,
        promoRewardLuc: platformPromoData?.reward_per_enrollment_luc || 0,
      });

      // Add student to General Community chat while they wait for confirmation
      try {
        const generalId = '00000000-0000-0000-0000-000000000000';
        await supabaseService.supabase
            .from('chat_channel_members')
            .upsert({ channel_id: generalId, user_id: user.id }, { onConflict: 'channel_id,user_id' });
      } catch (chatErr) {
        console.warn('Failed to join general chat:', chatErr);
      }

      await supabaseService.supabase.channel('admin_notifications').send({
        type: 'broadcast',
        event: 'PAYMENT_PENDING',
        payload: {
          userId: user.id,
          userName: user.user_metadata?.full_name || user.email,
          courseId: String(course.id),
          courseTitle: course.title,
          amount: finalPrice,
          bank: showBankTransfer,
          requestedAt: new Date().toISOString(),
        }
      });

      setStep("success");
    } catch (err) {
      console.error("Failed to create payment request:", err);
      setStep("checkout");
      setPaymentConfirmed(false);
      addToast("Something went wrong. Please try again.", "error");
    } finally {
      setIsLoading(false);
    }
  };

  const handleLucPayment = async () => {
    const hasAccepted = localStorage.getItem(
      `luc_integrity_accepted_${user.id}`,
    );
    if (!hasAccepted) {
      setShowIntegrityModal(true);
      return;
    }

    const lucPrice = nairaToLuc(finalPrice);

    if (wallet.balance < lucPrice) {
      addToast(
        "Insufficient LUC Credits. Earn more by completing courses!",
        "warning",
      );
      return;
    }

    setIsLoading(true);
    try {
      const result = await supabaseService.processWalletTransaction(
        user.id,
        -lucPrice,
        "course_purchase",
        `Purchased course: ${course.title}`,
        `purchase_${course.id}`,
      );

      if (result.success) {
        setStep("processing");
        setTimeout(() => {
            setStep('success');
            finalizePayment(course, `LUC_${Date.now()}`);
        }, 1500);
      } else {
        addToast(result.error || "Payment failed", "error");
        setIsLoading(false);
      }
    } catch (error) {
      console.error("LUC Payment Error:", error);
      addToast("An error occurred during transaction", "error");
      setIsLoading(false);
    }
  };

  const handleAcceptIntegrity = () => {
    localStorage.setItem(`luc_integrity_accepted_${user.id}`, "true");
    setShowIntegrityModal(false);
    handleLucPayment();
  };

  const handleIntakeComplete = async (data) => {
      setIntakeData(data);
      setShowIntakeModal(false);
      try {
          const studentsToSave = data.studentsData ? data.studentsData : [data];
          const record = {
              studentFullName: studentsToSave[0]?.studentFullName,
              studentAge: studentsToSave[0]?.studentAge,
              attendanceFormat: studentsToSave[0]?.attendanceFormat,
              track: studentsToSave[0]?.track,
              goal: studentsToSave[0]?.goal,
              user_id: user?.id,
              course_id: course?.id,
              course_title: course?.title,
              registration_type: data.registrationRole || 'student',
              parent_whatsapp: data.parentWhatsapp || null,
              parent_name: data.parentName || null,
              studentsData: studentsToSave
          };
          await supabaseService.client
              .from('camp_registrations')
              .insert([record]);
              
          if (studentsToSave.length > 1) {
              setPackageType('sibling');
              setNumChildren(studentsToSave.length);
              const discountPct = isEarlyWindow ? 15 : 10;
              addToast(`Sibling/Group Discount (${discountPct}%) auto-applied for ${studentsToSave.length} students!`, "success");
          }
      } catch (err) {
      console.warn("Camp intake save failed (non-blocking):", err.message);
    }
  };

  const handleApplyPromo = async () => {
    if (!promoInput.trim()) {
      addToast("Please enter a promo code", "error");
      return;
    }

    setVerifyingPlatformPromo(true);
    try {
      const promo = await supabaseService.validatePlatformPromoCode(promoInput.trim());
      if (promo) {
        setPlatformPromoData(promo);
        addToast(
          `Promo code applied! ${promo.discount_percent}% off` + (promo.reward_per_enrollment_luc > 0 ? ` — ${promo.holder_name} earns ${promo.reward_per_enrollment_luc} LUC` : ''),
          "success",
        );
        setPromoInput("");
      } else {
        addToast("Invalid or expired promo code", "error");
      }
    } catch (err) {
      addToast("Failed to validate promo code", "error");
    } finally {
      setVerifyingPlatformPromo(false);
    }
  };

  useEffect(() => {
    if (!isOpen) {
      setStep("checkout");
      setIsLoading(false);
      setShowBankTransfer(null);
      setPaymentConfirmed(false);
      setPlatformPromoData(null);
      setAutoAppliedPlatformPromo(false);
    }
  }, [isOpen]);

  if (!course) return null;

  return (
    <>
      <Modal
        isOpen={isOpen}
        onClose={onClose}
        title={step === "success" ? "Payment Processing" : "Secure Checkout"}
        size="md"
      >
        <div className="space-y-6">
          {step === "checkout" && (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
              {/* Course Recap */}
              <div className="flex gap-4 p-6 bg-slate-900 border border-white/10 rounded-[2rem] mb-8 relative overflow-hidden group">
                <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
                  <Icon name="ShieldCheck" size={60} />
                </div>
                <div className="w-24 h-24 rounded-2xl overflow-hidden shrink-0 border border-white/5 shadow-xl">
                  <img
                    src={course.image || course.thumbnail}
                    alt={course.title}
                    className="w-full h-full object-cover"
                  />
                </div>
                <div className="flex flex-col justify-center">
                  <h4 className="font-black text-white text-lg line-clamp-1 italic">
                    {course.title}
                  </h4>
                  <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mb-2">
                    {course.instructor}
                  </p>
                  <span className="text-2xl font-black text-secondary italic">
                    {(appliedPromo || discountLabel || platformPromoData) && (
                      <span className="line-through text-slate-500 mr-2 text-lg">
                        ₦{(course.price * (packageType === 'sibling' && numChildren > 1 ? numChildren : 1))?.toLocaleString()}
                      </span>
                    )}
                    ₦{finalPrice.toLocaleString()}
                  </span>
                  {discountLabel && (
                    <p className="text-[10px] font-black uppercase tracking-widest text-emerald-400 mt-1">
                      {discountLabel}
                    </p>
                  )}
                  {platformPromoData && platformPromoData.discount_percent > 0 && (
                    <p className="text-[10px] font-black uppercase tracking-widest text-primary mt-1">
                      {platformPromoData.code}: {platformPromoData.discount_percent}% off
                    </p>
                  )}
                </div>
              </div>

              {/* Discount Packages (Only for Summer Camp or courses that allow it) */}
              {course?.title?.toLowerCase().includes("summer camp") && (
                  <div className="mb-6 space-y-3">
                      <div className="flex items-center justify-between">
                          <h4 className="text-sm font-black italic uppercase text-slate-500 tracking-widest">Select Package</h4>
                          {isEarlyWindow && (
                              <span className="flex items-center gap-1.5 px-2 py-0.5 bg-emerald-500/10 border border-emerald-500/20 rounded-full text-[9px] font-black uppercase tracking-widest text-emerald-400">
                                  <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse" />
                                  Early Bird Active
                              </span>
                          )}
                      </div>
                      <div className="grid grid-cols-3 gap-3">
                          <button 
                              onClick={() => { setPackageType('standard'); setReferralValid(false); setInstructorPromoValid(false); setInstructorPromoData(null); setInstructorPromoCode(''); }}
                              className={`p-3 rounded-xl border text-left transition-all ${packageType === 'standard' ? 'border-primary bg-primary/10' : 'border-border bg-white dark:bg-black'} ${numChildren > 1 ? 'opacity-50 cursor-not-allowed' : ''}`}
                              disabled={numChildren > 1}
                          >
                              <div className="text-sm font-bold">Standard</div>
                              {!isEarlyWindow && <div className="text-[9px] text-slate-400 mt-0.5">Full price</div>}
                          </button>
                          <button 
                              onClick={() => { setPackageType('early_bird'); setReferralValid(false); setInstructorPromoValid(false); setInstructorPromoData(null); setInstructorPromoCode(''); }}
                              className={`p-3 rounded-xl border text-left transition-all ${packageType === 'early_bird' ? 'border-primary bg-primary/10' : 'border-border bg-white dark:bg-black'} ${numChildren > 1 ? 'opacity-50 cursor-not-allowed' : ''}`}
                              disabled={numChildren > 1}
                          >
                              <div className={`text-sm font-bold ${isEarlyWindow ? 'text-success' : 'text-slate-400'}`}>
                                  Early Bird {isEarlyWindow ? '(-10%)' : '(Expired)'}
                              </div>
                          </button>
                          <button 
                              onClick={() => { if(numChildren <= 1) { setPackageType('referral'); setInstructorPromoValid(false); setInstructorPromoData(null); setInstructorPromoCode(''); } }}
                              className={`p-3 rounded-xl border text-left transition-all ${packageType === 'referral' ? 'border-primary bg-primary/10' : 'border-border bg-white dark:bg-black'} ${numChildren > 1 ? 'opacity-50 cursor-not-allowed' : ''}`}
                              disabled={numChildren > 1}
                          >
                              <div className="text-sm font-bold text-secondary">Referred? (-10%)</div>
                          </button>
                      </div>
                      
                      {numChildren > 1 && (
                          <div className="p-4 bg-brand-blue/10 border border-brand-blue/30 rounded-xl flex items-center gap-4 mt-2 animate-in slide-in-from-bottom-2">
                              <Icon name="Users" size={24} className="text-brand-blue shrink-0" />
                              <div className="flex-1">
                                  <p className="text-sm font-black italic text-brand-blue">
                                      Sibling/Group Discount Applied! ({isEarlyWindow ? '15%' : '10%'} off)
                                  </p>
                                  <p className="text-xs text-brand-blue/80 font-medium">
                                      {isEarlyWindow
                                          ? `15% off applied for registering ${numChildren} children during Early Bird.`
                                          : `10% off applied for registering ${numChildren} children.`}
                                  </p>
                              </div>
                          </div>
                      )}

                      {packageType === 'referral' && numChildren <= 1 && (
                          <div className="p-4 bg-secondary/5 border border-secondary/20 rounded-xl flex gap-2 mt-2">
                              {autoAppliedReferral ? (
                                  <div className="flex-1 flex items-center gap-2 px-4 py-2 bg-success/5 border border-success/20 rounded-lg">
                                      <Icon name="Lock" size={14} className="text-success shrink-0" />
                                      <span className="flex-1 font-bold text-sm text-success">{referralCode}</span>
                                      <span className="text-[9px] font-black uppercase tracking-widest text-success bg-success/10 px-2 py-0.5 rounded-full">AUTO-APPLIED</span>
                                  </div>
                              ) : (
                                  <>
                                      <input 
                                          type="text" 
                                          placeholder="Referral Code" 
                                          value={referralCode}
                                          onChange={(e) => { setReferralCode(e.target.value); setReferralValid(false); }}
                                          disabled={referralValid}
                                          className="flex-1 px-4 py-2 bg-white dark:bg-black border border-border rounded-lg outline-none focus:border-secondary font-bold"
                                      />
                                      <Button 
                                          onClick={handleVerifyReferral} 
                                          loading={verifyingReferral}
                                          disabled={referralValid || !referralCode.trim()}
                                          className={`px-4 ${referralValid ? 'bg-success hover:bg-success/90 text-white' : 'bg-secondary'}`}
                                      >
                                          {referralValid ? 'Verified' : 'Verify'}
                                      </Button>
                                  </>
                              )}
                          </div>
                      )}

                      {!isEarlyWindow && packageType === 'standard' && numChildren <= 1 && (
                          <div className="p-3 bg-amber-500/10 border border-amber-500/20 rounded-xl flex items-center gap-3 mt-2">
                              <Icon name="Info" size={16} className="text-amber-500 shrink-0" />
                              <p className="text-[10px] font-bold text-amber-600">
                                  Early Bird window has closed. Use a Referral or Promo code for a discount.
                              </p>
                          </div>
                      )}
                  </div>
              )}

              {/* Intake Confirmation Banner */}
              {intakeData && (
                <div className="px-4 py-3 bg-amber-500/10 border border-amber-500/30 rounded-2xl mb-4 space-y-2">
                  <p className="text-xs font-black text-amber-600 uppercase tracking-widest">
                    {intakeData.registrationRole === 'parent' ? `Parent: ${intakeData.parentName || 'Guardian'}` : 'Enrolling'}
                  </p>
                  {(intakeData.studentsData || [intakeData]).map((s, i) => (
                      <div key={i} className="flex items-center gap-3">
                          <div className="w-7 h-7 bg-amber-500/20 rounded-full flex items-center justify-center text-amber-500 shrink-0">
                              <Icon name="User" size={13} />
                          </div>
                          <p className="text-sm font-bold flex-1 truncate">
                              {s.studentFullName} · Age {s.studentAge}
                          </p>
                          <span className={cn(
                              "text-[10px] font-black uppercase tracking-widest px-2 py-1 rounded-full",
                              s.attendanceFormat === "in-person" ? "bg-orange-100 text-orange-600" : "bg-primary/10 text-primary"
                          )}>
                              {s.attendanceFormat === "in-person" ? "🏢 Hub" : "💻 Online"}
                          </span>
                      </div>
                  ))}
                </div>
              )}

              {/* Promo Code Input — track enrollments only */}
              {course?.isTrack && !autoAppliedReferral && !autoAppliedPromo && !autoAppliedPlatformPromo && !platformPromoData && !instructorPromoValid && !referralValid && (
                <div className="mb-8">
                  <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground mb-2 block">
                    Have a Promo Code?
                  </label>
                  <div className="flex gap-2">
                    <input
                      type="text"
                      placeholder="Enter promo code..."
                      value={promoInput}
                      onChange={(e) =>
                        setPromoInput(e.target.value.toUpperCase())
                      }
                      disabled={instructorPromoValid}
                      className="flex-1 px-4 py-3 bg-muted border border-border rounded-xl focus:ring-2 focus:ring-primary outline-none font-bold tracking-widest uppercase text-sm"
                    />
                    <Button
                      onClick={handleApplyPromo}
                      disabled={verifyingPlatformPromo || instructorPromoValid || !promoInput.trim()}
                      loading={verifyingPlatformPromo}
                      className="px-6 rounded-xl font-bold"
                    >
                      APPLY
                    </Button>
                  </div>
                </div>
              )}

              {/* Platform Promo Applied Banner — track enrollments only */}
              {course?.isTrack && platformPromoData && (
                <div className="mb-6 p-4 bg-primary/5 border border-primary/20 rounded-2xl flex items-center gap-3">
                  <div className="w-10 h-10 bg-primary/20 rounded-full flex items-center justify-center shrink-0">
                    <Icon name="Tag" size={18} className="text-primary" />
                  </div>
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <span className="font-black text-sm tracking-widest uppercase text-primary">{platformPromoData.code}</span>
                      {autoAppliedPlatformPromo && (
                        <span className="text-[8px] font-black uppercase tracking-widest text-primary bg-primary/10 px-1.5 py-0.5 rounded">AUTO</span>
                      )}
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      {platformPromoData.discount_percent}% off by {platformPromoData.holder_name}
                      {platformPromoData.reward_per_enrollment_luc > 0 && ` · ${platformPromoData.reward_per_enrollment_luc} LUC reward`}
                    </p>
                  </div>
                  {!autoAppliedPlatformPromo && (
                    <button
                      onClick={() => setPlatformPromoData(null)}
                      className="w-8 h-8 rounded-lg bg-red-500/10 text-red-500 hover:bg-red-500 hover:text-white flex items-center justify-center transition-all"
                    >
                      <Icon name="X" size={14} />
                    </button>
                  )}
                </div>
              )}

              {/* Instructor Promo Code — auto-applied or manual input */}
              {course?.isTrack && autoAppliedPromo && instructorPromoValid && instructorPromoData && (
                <div className="mb-8">
                  <div className="flex items-center gap-2 px-4 py-3 bg-success/5 border border-success/20 rounded-xl">
                    <Icon name="Lock" size={14} className="text-success shrink-0" />
                    <span className="flex-1 font-bold text-sm text-success tracking-widest uppercase">{instructorPromoCode}</span>
                    <span className="text-[9px] font-black uppercase tracking-widest text-success bg-success/10 px-2 py-0.5 rounded-full">AUTO-APPLIED</span>
                  </div>
                  <p className="text-xs font-bold text-success mt-2 flex items-center gap-1">
                    <Icon name="CheckCircle2" size={12} />
                    Instructor code applied: {instructorPromoData.discount_percent}% off!
                  </p>
                </div>
              )}
              {course?.isTrack && !autoAppliedPromo && !platformPromoData && !referralValid && !autoAppliedPlatformPromo && !autoAppliedReferral && (
                <div className="mb-8">
                  <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground mb-2 block">
                    Have an Instructor Code?
                  </label>
                  <div className="flex gap-2">
                    <input
                      type="text"
                      placeholder="e.g. INSTR-CHIKE-3847"
                      value={instructorPromoCode}
                      onChange={(e) => {
                        setInstructorPromoCode(e.target.value.toUpperCase());
                        if (instructorPromoValid) {
                          setInstructorPromoValid(false);
                          setInstructorPromoData(null);
                        }
                      }}
                      disabled={instructorPromoValid || referralValid}
                      className="flex-1 px-4 py-3 bg-muted border border-border rounded-xl focus:ring-2 focus:ring-primary outline-none font-bold tracking-widest uppercase text-sm"
                    />
                    {instructorPromoValid ? (
                      <Button
                        variant="outline"
                        onClick={() => {
                          setInstructorPromoValid(false);
                          setInstructorPromoData(null);
                          setInstructorPromoCode('');
                        }}
                        className="px-4 text-red-500 border-red-200 bg-red-50 hover:bg-red-100 rounded-xl"
                      >
                        <Icon name="X" size={16} />
                      </Button>
                    ) : (
                      <Button
                        onClick={handleVerifyInstructorPromo}
                        loading={verifyingInstructorPromo}
                        disabled={referralValid || !instructorPromoCode.trim()}
                        className="px-6 rounded-xl font-bold"
                      >
                        VERIFY
                      </Button>
                    )}
                  </div>
                  {instructorPromoValid && instructorPromoData && (
                    <p className="text-xs font-bold text-success mt-2 flex items-center gap-1">
                      <Icon name="CheckCircle2" size={12} />
                      Instructor code applied: {instructorPromoData.discount_percent}% off!
                    </p>
                  )}
                  {!referralValid && !instructorPromoValid && (
                    <p className="text-[10px] text-muted-foreground mt-1">
                      Enter an instructor's promo code for 10% off their courses
                    </p>
                  )}
                </div>
              )}

              {/* Bank Transfer Trigger */}
              <div className="space-y-6">
                {!showBankTransfer ? (
                  <>
                    <div className="p-4 bg-secondary/5 border border-secondary/20 rounded-2xl flex items-center gap-3">
                      <div className="w-10 h-10 rounded-full bg-secondary/10 flex items-center justify-center text-secondary">
                        <Icon name="Lock" size={18} />
                      </div>
                      <p className="text-[10px] text-secondary font-black uppercase tracking-widest leading-relaxed">
                        Manual Bank Transfer · Admin Verified
                      </p>
                    </div>

                    <div className="grid grid-cols-1 gap-3">
                      <div className="grid grid-cols-2 gap-3">
                        <Button
                          fullWidth
                          onClick={() => handleBankTransfer('opay')}
                          loading={isLoading}
                          className="h-16 text-base font-black italic bg-emerald-600 hover:bg-emerald-700 text-white shadow-2xl shadow-emerald-500/20 rounded-2xl"
                        >
                          PAY WITH OPAY
                        </Button>
                        <Button
                          fullWidth
                          onClick={() => handleBankTransfer('kuda')}
                          loading={isLoading}
                          className="h-16 text-base font-black italic bg-purple-600 hover:bg-purple-700 text-white shadow-2xl shadow-purple-500/20 rounded-2xl"
                        >
                          PAY WITH KUDA
                        </Button>
                      </div>

                      <div className="relative flex items-center py-2">
                        <div className="flex-grow border-t border-border"></div>
                        <span className="flex-shrink mx-4 text-[10px] font-black uppercase tracking-widest text-muted-foreground">
                          OR
                        </span>
                        <div className="flex-grow border-t border-border"></div>
                      </div>

                      <Button
                        fullWidth
                        variant="outline"
                        onClick={handleLucPayment}
                        loading={isLoading}
                        disabled={wallet.balance < nairaToLuc(finalPrice)}
                        className="h-16 border-indigo-500/30 hover:bg-indigo-500/5 text-indigo-500 rounded-2xl flex flex-col items-center justify-center py-2"
                      >
                        <span className="text-sm font-black italic uppercase tracking-widest">
                          Pay with {nairaToLuc(finalPrice)} LUC
                        </span>
                        <span className="text-[10px] font-medium opacity-70">
                          Your Balance: {formatLuc(wallet.balance)}
                        </span>
                      </Button>
                    </div>
                  </>
                ) : (
                  <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                    {/* Bank Details Card */}
                    <div className="p-6 bg-gradient-to-br from-slate-900 to-slate-800 rounded-2xl border border-white/10 space-y-5">
                      <div className="flex items-center gap-3 mb-2">
                        <div className={`w-10 h-10 rounded-full flex items-center justify-center ${showBankTransfer === 'opay' ? 'bg-emerald-500/20' : 'bg-purple-500/20'}`}>
                          <Icon name="Building2" size={20} className={showBankTransfer === 'opay' ? 'text-emerald-400' : 'text-purple-400'} />
                        </div>
                        <div>
                          <p className={`text-[10px] font-black uppercase tracking-widest ${showBankTransfer === 'opay' ? 'text-emerald-400' : 'text-purple-400'}`}>Bank Transfer Details</p>
                          <p className="text-xs text-white/50 font-medium">Transfer exactly the amount below</p>
                        </div>
                      </div>

                      <div className="space-y-3">
                        <div className="flex justify-between items-center p-3 bg-white/5 rounded-xl">
                          <span className="text-xs text-white/50 font-bold">Bank</span>
                          <span className="text-sm font-black text-white">{bankDetails[showBankTransfer].bank}</span>
                        </div>
                        <div className="flex justify-between items-center p-3 bg-white/5 rounded-xl">
                          <span className="text-xs text-white/50 font-bold">Account Number</span>
                          <span className="text-sm font-black text-white tracking-widest">{bankDetails[showBankTransfer].accountNumber}</span>
                        </div>
                        <div className="flex justify-between items-center p-3 bg-white/5 rounded-xl">
                          <span className="text-xs text-white/50 font-bold">Account Name</span>
                          <span className="text-sm font-black text-white">{bankDetails[showBankTransfer].accountName}</span>
                        </div>
                        <div className={`flex justify-between items-center p-3 rounded-xl border ${showBankTransfer === 'opay' ? 'bg-emerald-500/10 border-emerald-500/20' : 'bg-purple-500/10 border-purple-500/20'}`}>
                          <span className={`text-xs font-bold ${showBankTransfer === 'opay' ? 'text-emerald-400' : 'text-purple-400'}`}>Amount</span>
                          <span className={`text-lg font-black ${showBankTransfer === 'opay' ? 'text-emerald-400' : 'text-purple-400'}`}>₦{finalPrice.toLocaleString()}</span>
                        </div>
                      </div>
                    </div>

                    {/* Confirmation */}
                    {!paymentConfirmed && (
                      <div className="space-y-4">
                        <p className="text-sm font-bold text-center text-muted-foreground">
                          Have you completed the payment?
                        </p>
                        <div className="grid grid-cols-2 gap-3">
                          <Button
                            fullWidth
                            onClick={handleConfirmPayment}
                            loading={isLoading}
                            className="h-14 font-black italic bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl"
                          >
                            YES, I'VE PAID
                          </Button>
                          <Button
                            fullWidth
                            variant="outline"
                            onClick={() => setShowBankTransfer(null)}
                            className="h-14 font-black italic rounded-2xl"
                          >
                            CANCEL
                          </Button>
                        </div>
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>
          )}

          {step === "processing" && (
            <div className="py-16 flex flex-col items-center justify-center text-center animate-in fade-in duration-500">
              <div className="relative w-28 h-28 mb-8">
                <div className="absolute inset-0 rounded-full bg-primary/5 animate-pulse" />
                <div className="absolute inset-1 border-[3px] border-primary/10 rounded-full" />
                <div className="absolute inset-1 border-[3px] border-primary rounded-full border-t-transparent animate-spin" />
                <div className="absolute inset-0 flex items-center justify-center">
                  <div className="w-12 h-12 bg-primary/10 rounded-full flex items-center justify-center">
                    <Icon name="Loader" size={24} className="text-primary animate-spin" style={{ animationDuration: '1.5s' }} />
                  </div>
                </div>
              </div>
              <h3 className="text-xl font-black italic text-foreground mb-3">
                Submitting Your Payment
              </h3>
              <p className="text-muted-foreground max-w-[260px] mx-auto text-sm leading-relaxed">
                Hold on a moment while we record your payment request...
              </p>
              <div className="flex items-center gap-1.5 mt-6 text-xs text-muted-foreground/60">
                <div className="w-1.5 h-1.5 rounded-full bg-primary/40 animate-bounce" style={{ animationDelay: '0ms' }} />
                <div className="w-1.5 h-1.5 rounded-full bg-primary/40 animate-bounce" style={{ animationDelay: '150ms' }} />
                <div className="w-1.5 h-1.5 rounded-full bg-primary/40 animate-bounce" style={{ animationDelay: '300ms' }} />
              </div>
            </div>
          )}

          {step === "success" && (
            <div className="py-8 flex flex-col items-center justify-center text-center animate-in fade-in duration-700">
              <div className="relative w-28 h-28 mb-6">
                <div className="absolute inset-0 rounded-full bg-emerald-500/10 animate-in zoom-in-50 duration-700" />
                <div className="absolute inset-0 flex items-center justify-center">
                  <div className="w-20 h-20 bg-emerald-500/15 rounded-full flex items-center justify-center border border-emerald-500/20">
                    <Icon name="CheckCircle2" size={40} className="text-emerald-500" />
                  </div>
                </div>
              </div>

              <h3 className="text-2xl font-black italic text-foreground mb-2">
                Request Received!
              </h3>
              <p className="text-muted-foreground text-sm max-w-[300px] mx-auto mb-6">
                Your payment request for{" "}
                <span className="font-bold text-foreground">"{course.title}"</span>{" "}
                has been submitted successfully.
              </p>

              {/* Payment Summary Card */}
              <div className="w-full max-w-[340px] bg-card border border-border rounded-2xl p-5 mb-6 text-left space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-xs text-muted-foreground font-medium">Amount</span>
                  <span className="text-lg font-black text-foreground">₦{finalPrice.toLocaleString()}</span>
                </div>
                <div className="h-px bg-border" />
                <div className="flex items-center justify-between">
                  <span className="text-xs text-muted-foreground font-medium">Bank</span>
                  <span className="text-sm font-bold text-foreground">{bankDetails[showBankTransfer]?.bank}</span>
                </div>
                <div className="h-px bg-border" />
                <div className="flex items-center justify-between">
                  <span className="text-xs text-muted-foreground font-medium">Status</span>
                  <span className="text-xs font-black uppercase tracking-widest text-amber-500 bg-amber-500/10 px-2.5 py-1 rounded-full">Pending Review</span>
                </div>
              </div>

              {/* What happens next */}
              <div className="w-full max-w-[340px] text-left mb-8">
                <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground mb-3">What happens next</p>
                <div className="space-y-2.5">
                  <div className="flex items-start gap-3">
                    <div className="w-5 h-5 rounded-full bg-primary/10 flex items-center justify-center shrink-0 mt-0.5">
                      <span className="text-[10px] font-black text-primary">1</span>
                    </div>
                    <p className="text-xs text-muted-foreground leading-relaxed">We verify your transfer within 120 seconds</p>
                  </div>
                  <div className="flex items-start gap-3">
                    <div className="w-5 h-5 rounded-full bg-primary/10 flex items-center justify-center shrink-0 mt-0.5">
                      <span className="text-[10px] font-black text-primary">2</span>
                    </div>
                    <p className="text-xs text-muted-foreground leading-relaxed">You receive a notification once confirmed</p>
                  </div>
                  <div className="flex items-start gap-3">
                    <div className="w-5 h-5 rounded-full bg-primary/10 flex items-center justify-center shrink-0 mt-0.5">
                      <span className="text-[10px] font-black text-primary">3</span>
                    </div>
                    <p className="text-xs text-muted-foreground leading-relaxed">Your course unlocks instantly in your library</p>
                  </div>
                </div>
              </div>

              <Button
                fullWidth
                className="h-14 font-black italic rounded-2xl text-base"
                onClick={onClose}
                iconName="ArrowRight"
                iconPosition="right"
              >
                BACK TO ACADEMY
              </Button>
            </div>
          )}
        </div>
      </Modal>

      <IntegrityAgreementModal
        isOpen={showIntegrityModal}
        onClose={() => setShowIntegrityModal(false)}
        onAccept={handleAcceptIntegrity}
      />

      <CampIntakeModal
          isOpen={showIntakeModal}
          onClose={() => { setShowIntakeModal(false); onClose(); }}
          course={course}
          numStudents={packageType === 'sibling' ? numChildren : 1}
          onIntakeComplete={handleIntakeComplete}
      />
    </>
  );
};

export default PaymentModal;
